-- Polymarket Copy Trading Database Schema\n-- Initializes tables for wallet tracking, copy trades, and PnL\n\n-- Enable UUID extension\nCREATE EXTENSION IF NOT EXISTS \"uuid-ossp\";\n\n-- ============================================\n-- FOLLOWED WALLETS TABLE\n-- ============================================\nCREATE TABLE IF NOT EXISTS followed_wallets (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    wallet_address VARCHAR(66) NOT NULL UNIQUE,\n    wallet_name VARCHAR(255),\n    followed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    is_active BOOLEAN DEFAULT true,\n    \n    -- Profitability metrics (updated hourly)\n    lifetime_pnl_usd NUMERIC(15, 2) DEFAULT 0,\n    trades_90d INTEGER DEFAULT 0,\n    win_rate NUMERIC(5, 4) DEFAULT 0,\n    total_volume_usd NUMERIC(15, 2) DEFAULT 0,\n    \n    -- Category breakdown\n    crypto_pnl NUMERIC(15, 2) DEFAULT 0,\n    politics_pnl NUMERIC(15, 2) DEFAULT 0,\n    sports_pnl NUMERIC(15, 2) DEFAULT 0,\n    other_pnl NUMERIC(15, 2) DEFAULT 0,\n    \n    -- Metadata\n    last_updated TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE INDEX idx_followed_wallets_address ON followed_wallets(wallet_address);\nCREATE INDEX idx_followed_wallets_active ON followed_wallets(is_active) WHERE is_active = true;\nCREATE INDEX idx_followed_wallets_pnl ON followed_wallets(lifetime_pnl_usd DESC);\n\n-- ============================================\n-- COPY TRADES TABLE\n-- ============================================\nCREATE TABLE IF NOT EXISTS copy_trades (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    wallet_id UUID REFERENCES followed_wallets(id) ON DELETE CASCADE,\n    \n    -- Trade details\n    market_id VARCHAR(255) NOT NULL,\n    market_question VARCHAR(500),\n    outcome VARCHAR(100),\n    side VARCHAR(10) CHECK (side IN ('YES', 'NO')),\n    \n    -- Position details\n    shares_purchased NUMERIC(15, 4) NOT NULL,\n    avg_price NUMERIC(6, 4) NOT NULL,\n    total_cost_usd NUMERIC(15, 2) NOT NULL,\n    \n    -- Leader's trade (for reference)\n    leader_wallet VARCHAR(66),\n    leader_shares NUMERIC(15, 4),\n    leader_avg_price NUMERIC(6, 4),\n    copied_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Status\n    status VARCHAR(20) DEFAULT 'open' CHECK (status IN ('open', 'closed', 'stopped')),\n    closed_at TIMESTAMP WITH TIME ZONE,\n    \n    -- PnL tracking\n    realized_pnl_usd NUMERIC(15, 2) DEFAULT 0,\n    unrealized_pnl_usd NUMERIC(15, 2) DEFAULT 0,\n    \n    -- Metadata\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE INDEX idx_copy_trades_wallet ON copy_trades(wallet_id);\nCREATE INDEX idx_copy_trades_status ON copy_trades(status);\nCREATE INDEX idx_copy_trades_market ON copy_trades(market_id);\nCREATE INDEX idx_copy_trades_created ON copy_trades(created_at DESC);\n\n-- ============================================\n-- WHALE TRADES LOG (FOR ALERTS)\n-- ============================================\nCREATE TABLE IF NOT EXISTS whale_trades_log (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    wallet_address VARCHAR(66) NOT NULL,\n    \n    -- Trade details\n    market_id VARCHAR(255) NOT NULL,\n    market_question VARCHAR(500),\n    outcome VARCHAR(100),\n    side VARCHAR(10),\n    \n    -- Trade size\n    shares NUMERIC(15, 4) NOT NULL,\n    price NUMERIC(6, 4) NOT NULL,\n    total_usd NUMERIC(15, 2) NOT NULL,\n    \n    -- Timestamps\n    trade_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,\n    logged_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Whether this triggered a copy\n    was_copied BOOLEAN DEFAULT false,\n    copy_trade_id UUID REFERENCES copy_trades(id),\n    \n    INDEX idx_whale_trades_wallet ON whale_trades_log(wallet_address),\n    INDEX idx_whale_trades_timestamp ON whale_trades_log(trade_timestamp DESC)\n);\n\n-- ============================================\n-- ALERTS CONFIGURATION\n-- ============================================\nCREATE TABLE IF NOT EXISTS alert_config (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    chat_id VARCHAR(100) NOT NULL,\n    \n    -- Alert preferences\n    alerts_enabled BOOLEAN DEFAULT true,\n    min_trade_size_usd NUMERIC(15, 2) DEFAULT 1000,\n    categories TEXT[] DEFAULT ARRAY['crypto', 'politics', 'sports', 'other'],\n    \n    -- Notification settings\n    notify_on_new_trade BOOLEAN DEFAULT true,\n    notify_on_close BOOLEAN DEFAULT true,\n    notify_on_pnl_threshold BOOLEAN DEFAULT false,\n    pnl_threshold_usd NUMERIC(15, 2) DEFAULT 100,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\n-- ============================================\n-- PERFORMANCE METRICS\n-- ============================================\nCREATE TABLE IF NOT EXISTS performance_metrics (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    date DATE NOT NULL DEFAULT CURRENT_DATE,\n    \n    -- Daily stats\n    total_trades INTEGER DEFAULT 0,\n    winning_trades INTEGER DEFAULT 0,\n    losing_trades INTEGER DEFAULT 0,\n    \n    -- PnL\n    daily_pnl_usd NUMERIC(15, 2) DEFAULT 0,\n    cumulative_pnl_usd NUMERIC(15, 2) DEFAULT 0,\n    \n    -- Copy trading stats\n    total_copied_usd NUMERIC(15, 2) DEFAULT 0,\n    avg_position_size_usd NUMERIC(15, 2) DEFAULT 0,\n    \n    -- Latency metrics\n    avg_copy_latency_secs NUMERIC(10, 2) DEFAULT 0,\n    max_copy_latency_secs NUMERIC(10, 2) DEFAULT 0,\n    \n    UNIQUE(date)\n);\n\nCREATE INDEX idx_performance_metrics_date ON performance_metrics(date DESC);\n\n-- ============================================\n-- MCP SERVER LOGS\n-- ============================================\nCREATE TABLE IF NOT EXISTS mcp_logs (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    server_name VARCHAR(50) NOT NULL,\n    log_level VARCHAR(20) NOT NULL,\n    message TEXT NOT NULL,\n    metadata JSONB,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE INDEX idx_mcp_logs_server ON mcp_logs(server_name);\nCREATE INDEX idx_mcp_logs_level ON mcp_logs(log_level);\nCREATE INDEX idx_mcp_logs_created ON mcp_logs(created_at DESC);\n\n-- ============================================\n-- INSERT DEFAULT ALERT CONFIG\n-- ============================================\nINSERT INTO alert_config (chat_id, alerts_enabled, min_trade_size_usd)\nVALUES ('default', true, 1000)\nON CONFLICT DO NOTHING;\n\n-- ============================================\n-- VIEWS FOR COMMON QUERIES\n-- ============================================\n\n-- Active copy trades with current PnL\nCREATE OR REPLACE VIEW active_copy_trades AS\nSELECT \n    ct.id,\n    ct.market_question,\n    ct.outcome,\n    ct.side,\n    ct.shares_purchased,\n    ct.avg_price,\n    ct.total_cost_usd,\n    ct.unrealized_pnl_usd,\n    ct.copied_at,\n    fw.wallet_address as leader_wallet,\n    fw.win_rate as leader_win_rate\nFROM copy_trades ct\nJOIN followed_wallets fw ON ct.wallet_id = fw.id\nWHERE ct.status = 'open'\nORDER BY ct.created_at DESC;\n\n-- Top followed wallets by PnL\nCREATE OR REPLACE VIEW top_followed_wallets AS\nSELECT \n    wallet_address,\n    wallet_name,\n    lifetime_pnl_usd,\n    trades_90d,\n    win_rate,\n    total_volume_usd,\n    followed_at\nFROM followed_wallets\nWHERE is_active = true\nORDER BY lifetime_pnl_usd DESC\nLIMIT 20;\n\n-- Daily performance summary\nCREATE OR REPLACE VIEW daily_performance AS\nSELECT \n    date,\n    total_trades,\n    winning_trades,\n    losing_trades,\n    daily_pnl_usd,\n    cumulative_pnl_usd,\n    ROUND((winning_trades::NUMERIC / NULLIF(total_trades, 0) * 100), 2) as win_rate_pct\nFROM performance_metrics\nORDER BY date DESC\nLIMIT 30;\n\nCOMMENT ON TABLE followed_wallets IS 'Wallets being tracked for copy trading';\nCOMMENT ON TABLE copy_trades IS 'Executed copy trades with PnL tracking';\nCOMMENT ON TABLE whale_trades_log IS 'Log of all whale trades detected';\nCOMMENT ON TABLE alert_config IS 'Telegram alert preferences';\nCOMMENT ON TABLE performance_metrics IS 'Daily performance aggregation';